package com.javaintro;

public class Swaptwonumbers {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=10;
		int b=20;
		int temp;
		
	
	System.out.println(a);
	System.out.println(b);
	System.out.println();
	temp=a;
	a=b;
	b=temp;
	System.out.println("After swaping");
	System.out.println(a);
	System.out.println(b);
	
	}

}
